let profileCropState=null;
function profileMediaUrl(path){return path?cloud.storage.from('iasd-images').getPublicUrl(path).data.publicUrl:''}
function profileImageStyle(kind){const x=Number(myProfile?.[kind+'_x']??50),y=Number(myProfile?.[kind+'_y']??50),z=Number(myProfile?.[kind+'_zoom']??1);return 'object-position:'+x+'% '+y+'%!important;transform:scale('+z+')!important;transform-origin:50% 50%!important;'}
