function renderProfileCrop(){const st=profileCropState;if(!st)return;let root=$('profile-crop-root');if(!root){root=document.createElement('div');root.id='profile-crop-root';document.body.appendChild(root)}root.innerHTML='<div class="profile-crop-backdrop" onclick="closeProfileCrop()"></div><section class="profile-crop-dialog"><h3>'+(st.kind==='avatar'?'Enquadrar foto de perfil':'Enquadrar foto de capa')+'</h3><div class="profile-crop-stage '+(st.kind==='avatar'?'avatar-stage':'')+'"><img id="profile-crop-image" src="'+st.url+'" alt=""></div><label>Horizontal<input type="range" min="0" max="100" value="'+st.x+'" oninput="updateProfileCrop(\'x\',this.value)"></label><label>Vertical<input type="range" min="0" max="100" value="'+st.y+'" oninput="updateProfileCrop(\'y\',this.value)"></label><label>Zoom<input type="range" min="1" max="2.4" step=".02" value="'+st.zoom+'" oninput="updateProfileCrop(\'zoom\',this.value)"></label><div class="profile-crop-actions"><button onclick="chooseProfileMedia(profileCropState.kind)">Trocar imagem</button><button class="danger" onclick="removeProfileMedia(profileCropState.kind)">Apagar</button><button onclick="closeProfileCrop()">Cancelar</button><button class="primary" onclick="saveProfileMedia()">Salvar imagem</button></div></section>';updateProfileCrop()}
