function closeProfileCrop(){if(profileCropState?.url)URL.revokeObjectURL(profileCropState.url);profileCropState=null;$('profile-crop-root')?.remove()}async function removeProfileMedia(kind){if(!cloudUser)return;const path=myProfile?.[kind+'_path']||null;if(!path){closeProfileCrop();return}if(!(await IASDDialog.confirm('Apagar esta imagem?')))return;const patch={user_id:cloudUser.id,[kind+'_path']:null,[kind+'_x']:50,[kind+'_y']:50,[kind+'_zoom']:1,updated_at:new Date().toISOString()};const saved=await cloud.from('iasd_profiles').upsert(patch);if(saved.error)return alert('Não foi possível apagar a imagem: '+saved.error.message);await cloud.storage.from('iasd-images').remove([path]);myProfile={...(myProfile||{}),...patch};closeProfileCrop();syncAccountUI();render()}
