function gameModeCards(){if(current==='Jogo'&&window.IASDPages?.gameCards)return IASDPages.gameCards();const solo=[['quiz','⚡','Quiz Relâmpago','Responda rápido e mantenha o combo.'],['who','◉','Quem Sou Eu?','Descubra personagens pelas pistas.'],['order','⇅','Linha do Tempo','Organize acontecimentos bíblicos.'],['memory','▦','Memória Bíblica','Encontre os pares relacionados.']].map(([m,i,t,d])=>'<button class="game-mode-card" onclick="gameSfx(\'click\');startGameMode(\''+m+'\')"><span>'+i+'</span><strong>'+t+'</strong><small>'+d+'</small></button>').join('');return '<div class="game-mode-grid">'+solo+'<button class="game-mode-card game-mode-live" onclick="gameSfx(\'start\');openCollectiveGame()"><span>◉</span><strong>Jogo Coletivo</strong><small>Crie uma sala, conecte os celulares e jogue ao vivo no telão.</small></button></div>'}
