function gameHubMarkup(compact=false){const me=gameRanking.find(x=>x.user_id===cloudUser?.id);return '<section class="game-hub '+(compact?'game-hub-profile':'')+'"><div class="game-hero"><div><span class="game-kicker">DESAFIO DA PALAVRA</span><h2>Jogue. Aprenda. Suba no ranking.</h2><p>Modos rápidos, desafios bíblicos e conquistas para toda a comunidade.</p></div><div class="game-level"><span>NÍVEL</span><strong>'+(me?Math.max(1,Math.floor(Number(me.score||0)/500)+1):1)+'</strong><small>'+(me?Number(me.score||0).toLocaleString('pt-BR'):0)+' pts</small></div></div><div id="game-stage">'+gameModeCards()+'</div><div class="game-ranking-preview">'+gameRankingMarkup(5)+'</div></section>'}
function gameHomeRanking(){if(!cloudUser)return '';setTimeout(loadGameRanking,0);return '<section class="home-ranking">'+gameRankingMarkup(3)+'</section>'}
function gamePage(){if(!cloudUser)return '<div class="panel game-login"><h2>Desafio da Palavra</h2><p>Entre para jogar, salvar seu progresso e participar do ranking.</p><button class="primary" onclick="openAuthModal()">Entrar ou criar conta</button></div>';setTimeout(loadGameRanking,0);return '<div class="game-page">'+(window.IASDPages?.games?IASDPages.games():gameHubMarkup(false))+'</div>'}
async function loadGameRanking(force=false){if(!cloud||gameRankingBusy||(gameRankingLoaded&&!force))return;gameRankingBusy=true;const r=await cloud.from('iasd_game_stats').select('user_id,score,correct_answers,total_answers,best_streak,games_played,updated_at,iasd_profiles(full_name,avatar_path)').order('score',{ascending:false}).limit(50);gameRankingBusy=false;if(!r.error){gameRanking=r.data||[];gameRankingLoaded=true;if(['Jogo','Perfil'].includes(current))render()}}
function gameRankingMarkup(limit=5){const rows=gameRanking.slice(0,limit);return '<div class="ranking-head"><div><span>RANKING</span><h3>Destaques da comunidade</h3></div><button onclick="go(\'Jogo\')">Ver completo →</button></div><div class="ranking-list">'+(rows.length?rows.map((x,i)=>{const p=x.iasd_profiles||{},avatar=p.avatar_path?'<img src="'+esc(profileMediaUrl(p.avatar_path))+'" alt="">':defaultProfileAvatar(),accuracy=x.total_answers?Math.round(x.correct_answers*100/x.total_answers):0;return '<article class="ranking-row '+(i<3?'podium':'')+'"><b class="rank-pos">'+(i===0?'🏆':i===1?'🥈':i===2?'🥉':(i+1))+'</b><span class="rank-avatar">'+avatar+'</span><div class="rank-person"><strong>'+esc(p.full_name||'Participante')+'</strong><small>'+accuracy+'% precisão · sequência '+Number(x.best_streak||0)+'</small></div><strong class="rank-score">'+Number(x.score||0).toLocaleString('pt-BR')+' pts</strong></article>'}).join(''):'<p class="ranking-empty">O ranking começa com a primeira partida.</p>')+'</div>'}
function startGameMode(mode){if(window.IASDSolo&&mode){IASDSolo.open(mode);return}gameSession={mode,score:0,streak:0,index:0,correct:0,answered:0};renderGameRound()}
function gameStage(){return document.getElementById('game-stage')}
function renderGameRound(){const stage=gameStage();if(!stage)return;if(gameSession.mode==='quiz'){const q=GAME_QUIZ[gameSession.index%GAME_QUIZ.length];stage.innerHTML='<div class="game-round"><div class="game-status"><span>⚡ '+gameSession.score+' pts</span><span>Combo ×'+Math.max(1,gameSession.streak)+'</span></div><span class="game-type">QUIZ RELÂMPAGO</span><h3>'+esc(q.q)+'</h3><div class="game-answers">'+shuffle(q.o).map(o=>'<button onclick="answerQuiz('+JSON.stringify(o).replace(/"/g,'&quot;')+')">'+esc(o)+'</button>').join('')+'</div><small class="game-ref">'+q.r+'</small></div>';return}if(gameSession.mode==='who'){const q=GAME_WHO[gameSession.index%GAME_WHO.length],shown=Math.min(3,Math.max(1,gameSession.index%3+1));stage.innerHTML='<div class="game-round"><div class="game-status"><span>◉ '+gameSession.score+' pts</span><span>Pistas '+shown+'/3</span></div><span class="game-type">QUEM SOU EU?</span><div class="clue-stack">'+q.clues.slice(0,shown).map((c,i)=>'<p><b>'+(i+1)+'</b>'+esc(c)+'</p>').join('')+'</div><input id="who-answer" placeholder="Digite o personagem"><button class="game-main-action" onclick="answerWho()">Responder</button><small class="game-ref">'+q.ref+'</small></div>';return}if(gameSession.mode==='order'){const q=GAME_ORDER[gameSession.index%GAME_ORDER.length];if(!gameSession.currentOrder)gameSession.currentOrder=shuffle(q.items);stage.innerHTML='<div class="game-round"><div class="game-status"><span>⇅ '+gameSession.score+' pts</span><span>Ordem bíblica</span></div><span class="game-type">LINHA DO TEMPO</span><h3>'+q.title+'</h3><div class="order-list">'+gameSession.currentOrder.map((x,i)=>'<div class="order-item"><span>'+(i+1)+'</span><strong>'+esc(x)+'</strong><button onclick="moveOrder('+i+',-1)">↑</button><button onclick="moveOrder('+i+',1)">↓</button></div>').join('')+'</div><button class="game-main-action" onclick="checkOrder()">Confirmar ordem</button><small class="game-ref">'+q.ref+'</small></div>';return}if(gameSession.mode==='memory'){if(!gameSession.memory){const pairs=[['Arca','Noé'],['Gigante','Davi'],['Leões','Daniel'],['Rainha','Ester'],['Maná','Deserto'],['Jericó','Josué']];gameSession.memory=shuffle(pairs.flatMap((p,i)=>p.map((v,side)=>({v,pair:i,side}))));gameSession.open=[];gameSession.matched=[]}stage.innerHTML='<div class="game-round memory-round"><div class="game-status"><span>▦ '+gameSession.score+' pts</span><span>'+gameSession.matched.length/2+' de '+gameSession.memory.length/2+' pares</span></div><span class="game-type">MEMÓRIA BÍBLICA</span><h3>Encontre os pares relacionados</h3><p class="muted">Toque em duas cartas. Combine cada elemento com seu par bíblico.</p><div class="memory-grid memory-grid-rich">'+gameSession.memory.map((c,i)=>'<button id="mem-'+i+'" class="memory-card '+(gameSession.matched.includes(i)?'matched':'')+'" onclick="flipMemory('+i+')"><span class="memory-card-back">✦</span><span class="memory-card-value">'+(gameSession.matched.includes(i)?esc(c.v):'')+'</span></button>').join('')+'</div><button class="game-main-action" onclick="startGameMode(\'memory\')">↻ Embaralhar novamente</button></div>'}}
function gameFeedback(ok,text,ref){const stage=gameStage();if(!stage)return;const box=document.createElement('div');box.className='game-feedback '+(ok?'ok':'bad');box.innerHTML='<strong>'+(ok?'✓ Acertou!':'✦ Continue tentando')+'</strong><span>'+esc(text)+'</span><small>'+esc(ref||'')+'</small>';stage.appendChild(box);setTimeout(()=>{gameSession.index++;gameSession.currentOrder=null;renderGameRound()},850)}
function scoreGame(ok,base=100){gameSession.answered++;if(ok){gameSession.correct++;gameSession.streak++;gameSession.score+=base+Math.min(100,gameSession.streak*10)}else gameSession.streak=0;if(gameSession.answered%5===0)saveGameProgress()}
function answerQuiz(v){const q=GAME_QUIZ[gameSession.index%GAME_QUIZ.length],ok=v===q.a;gameSfx(ok?'correct':'wrong');scoreGame(ok);gameFeedback(ok,ok?q.a:'Resposta: '+q.a,q.r)}
function answerWho(){const q=GAME_WHO[gameSession.index%GAME_WHO.length],v=($('who-answer')?.value||'').trim().toLowerCase(),ok=v===q.answer.toLowerCase();gameSfx(ok?'correct':'wrong');scoreGame(ok,150);gameFeedback(ok,ok?q.answer:'Era '+q.answer,q.ref)}
function moveOrder(i,d){const n=i+d;if(n<0||n>=gameSession.currentOrder.length)return;[gameSession.currentOrder[i],gameSession.currentOrder[n]]=[gameSession.currentOrder[n],gameSession.currentOrder[i]];renderGameRound()}
function checkOrder(){const q=GAME_ORDER[gameSession.index%GAME_ORDER.length],ok=gameSession.currentOrder.every((x,i)=>x===q.items[i]);gameSfx(ok?'correct':'wrong');scoreGame(ok,180);gameFeedback(ok,ok?'Sequência correta.':'Revise a sequência.',q.ref)}
function flipMemory(i){if(gameSession.matched.includes(i)||gameSession.open.includes(i)||gameSession.open.length>=2)return;gameSfx('click');gameSession.open.push(i);const b=$('mem-'+i);b.classList.add('open');b.innerHTML='<span>'+esc(gameSession.memory[i].v)+'</span>';if(gameSession.open.length===2){const [a,c]=gameSession.open,ok=gameSession.memory[a].pair===gameSession.memory[c].pair;setTimeout(()=>{if(ok){gameSfx('correct');gameSession.matched.push(a,c);gameSession.score+=120;gameSession.correct++;gameSession.streak++}else{gameSfx('wrong');gameSession.streak=0;}gameSession.answered++;gameSession.open=[];if(gameSession.matched.length===gameSession.memory.length){saveGameProgress();gameSession.memory=null;gameSession.index++}renderGameRound()},550)}}
async function saveGameProgress(){if(!cloudUser||!cloud||!gameSession.answered)return;const payload={p_score:Math.max(0,Math.min(5000,Math.round(gameSession.score))),p_correct:Math.max(0,Math.round(gameSession.correct)),p_total:Math.max(1,Math.min(50,Math.round(gameSession.answered))),p_streak:Math.max(0,Math.min(50,Math.round(gameSession.streak)))};const r=await cloud.rpc('iasd_record_game_result',payload);if(!r.error){gameSession.score=0;gameSession.correct=0;gameSession.answered=0;gameRankingLoaded=false;loadGameRanking(true)}}
function mobileMenuPage(){const items=[['Painel','⌂','Início'],['Cronograma','▦','Cronogramas'],['Escalas','☷','Escalas'],['Sonoplastia','♫','IASD Projetor'],['Bíblia','▤','Bíblia'],['Lição da Escola Sabatina','▥','Lição da Escola Sabatina'],['Palavra em Cena','✦','Palavra em Cena'],['Jogo','◆','Jogo']].concat(window.IASDAccess?.canStudy(cloudRole)?[['Estudo','▤','Sala de Estudo']]:[]);return '<div class="mobile-menu-page"><div class="mobile-menu-head"><span>IASD APP</span><h2>Menu</h2><p>As mesmas áreas do computador, adaptadas para o celular.</p></div><div class="mobile-menu-list">'+items.map(([t,i,n])=>'<button onclick="go(\''+t+'\')"><span>'+i+'</span><strong>'+n+'</strong><em>›</em></button>').join('')+customTabs.map(t=>'<button onclick="go(\'custom:'+t.id+'\')"><span>'+esc(t.icon||'✦')+'</span><strong>'+esc(t.title)+'</strong><em>›</em></button>').join('')+'</div>'+(canSendSoundAlert()?'<div class="mobile-menu-group"><small>EQUIPE</small><button onclick="go(\'Alertas\')"><span>🔔</span><strong>Alertar sonoplastia</strong><em>›</em></button></div>':'')+(window.IASDAccess?.canGivePerms(cloudRole)?'<div class="mobile-menu-group"><small>ACESSOS</small><button onclick="go(\'Cargos\')"><span>🔑</span><strong>Cargos e acessos</strong><em>›</em></button></div>':'')+(canManageSite()?'<div class="mobile-menu-group"><small>ADMINISTRAÇÃO</small>'+(cloudRole==='founder'?'<button onclick="go(\'Fundador\')"><span>♛</span><strong>Painel do fundador</strong><em>›</em></button>':'')+'<button onclick="go(\'Acervo\')"><span>▧</span><strong>Acervo do site</strong><em>›</em></button></div>':'')+'</div>'}
