function openProfileEditor(){if(!cloudUser)return openAuthModal();const root=$('inline-editor-root');root.innerHTML='<div class="iasd-edit-backdrop" onclick="closeInlineTextEditor()"></div><section class="iasd-edit-dialog profile-edit-dialog" role="dialog" aria-modal="true"><div class="iasd-edit-head"><strong>Editar minhas informações</strong><button onclick="closeInlineTextEditor()">✕</button></div><label>Nome completo</label><input id="profile-name" value="'+esc(myProfile?.full_name||'')+'"><label>Igreja / congregação</label><input id="profile-church" value="IASD - Caldas do Jorro" readonly><label>Função na igreja</label>'+churchPositionSelect("profile-position",myProfile?.church_position||"")+'<label>Ministério / observações</label><input id="profile-ministry" value="'+esc(myProfile?.ministry||'')+'"><label>Telefone (opcional)</label><input id="profile-phone" type="tel" value="'+esc(myProfile?.phone||'')+'"><p id="profile-feedback"></p><div class="iasd-edit-actions"><button onclick="closeInlineTextEditor()">Cancelar</button><button id="profile-save" class="primary" onclick="saveMyProfile()">Salvar alterações</button></div></section>'}
