function itemList(key){return '<ul>'+data[key].map((x,i)=>'<li>'+esc(x)+' <button onclick="removeItem(\''+key+'\','+i+')">Excluir</button> <button onclick="project('+JSON.stringify(x).replace(/"/g,'&quot;')+')">Projetar</button></li>').join('')+'</ul>'}function removeItem(key,i){data[key].splice(i,1);save()}function addItem(key){const el=$('new-'+key);if(el.value.trim()){data[key].push(el.value.trim());save()}}function parseSchedule(x){const parts=String(x).split(/\s+[—–-]\s+/);return {time:/^\d{1,2}:\d{2}$/.test(parts[0]||'')?parts.shift():'•',title:parts.shift()||String(x),person:parts.join(' — ')}}function scheduleList(items,editable=false){return items.length?items.map((x,i)=>{const a=parseSchedule(x);return '<div class="schedule"><span class="time">'+esc(a.time)+'</span><div class="event"><strong>'+esc(a.title)+'</strong>'+(a.person?'<small>'+esc(a.person)+'</small>':'')+(editable?'<div class="itemactions"><button onclick="project(cloudSchedules.find(g=>g.id===selectedSchedule).items['+i+'])">Projetar</button><button onclick="removeScheduleLine('+i+')">Excluir atividade</button></div>':'')+'</div></div>'}).join(''):'<p class="muted">Nenhuma atividade cadastrada.</p>'}function datasParse(x,i){const raw=String(x),m=/^\s*(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\s*[—–-]\s*(.+)$/.exec(raw);const t0=new Date();t0.setHours(0,0,0,0);if(!m)return{i,raw,name:raw,date:null,diff:null};const dd=+m[1],mm=+m[2];let y=m[3]?+m[3]:t0.getFullYear();if(m[3]&&y<100)y+=2000;let d=new Date(y,mm-1,dd);if(!m[3]&&d<t0)d=new Date(y+1,mm-1,dd);if(d.getMonth()!==mm-1)return{i,raw,name:raw,date:null,diff:null};return{i,raw,name:m[4].trim(),date:d,diff:Math.round((d-t0)/864e5)}}
function datasAddAurora(){const d=($('dt-d').value||'').trim(),n=($('dt-n').value||'').trim();if(!n){$('dt-n').focus();return}if(d&&!/^\d{1,2}\/\d{1,2}(\/\d{2,4})?$/.test(d)){alert('Use a data no formato dd/mm ou dd/mm/aaaa.');$('dt-d').focus();return}$('new-datas').value=d?d+' — '+n:n;addItem('datas')}
function datasAurora(){const MS=['JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'],CL=['#ffc15e;background:rgba(255,193,94,.15)','#35f0b9;background:rgba(53,240,185,.14)','#ff7d98;background:rgba(255,106,136,.14)','#a99bff;background:rgba(169,155,255,.15)'];const items=(data.datas||[]).map(datasParse);const dated=items.filter(x=>x.date).sort((a,b)=>a.date-b.date),undated=items.filter(x=>!x.date);const rel=n=>n===0?'Hoje':n===1?'Amanhã':'Em '+n+' dias';const btn=x=>'<button type="button" class="au-dt-b" onclick="project('+JSON.stringify(x.raw).replace(/"/g,'&quot;')+')">Projetar</button><button type="button" class="au-dt-b del" onclick="removeItem(\'datas\','+x.i+')">Excluir</button>';let html='',last='',ci=-1;dated.forEach(x=>{const k=x.date.getFullYear()+'-'+x.date.getMonth();if(k!==last){last=k;ci=(ci+1)%CL.length;html+='<div class="au-dt-mh">'+MS[x.date.getMonth()]+(x.date.getFullYear()!==new Date().getFullYear()?' '+x.date.getFullYear():'')+'</div>'}html+='<div class="au-dt-ev"><div class="au-dt-db" style="color:'+CL[ci]+'"><b>'+String(x.date.getDate()).padStart(2,'0')+'</b><small>'+MS[x.date.getMonth()].slice(0,3)+'</small></div><div class="au-dt-tx"><h3>'+esc(x.name)+'</h3><small>'+(x.diff<0?'Já passou':rel(x.diff))+'</small></div>'+btn(x)+'</div>'});if(undated.length){html+='<div class="au-dt-mh">SEM DATA</div>'+undated.map(x=>'<div class="au-dt-ev"><div class="au-dt-db" style="color:#a39db3;background:rgba(255,255,255,.07)"><b>•</b></div><div class="au-dt-tx"><h3>'+esc(x.name)+'</h3></div>'+btn(x)+'</div>').join('')}if(!items.length)html='<p class="au-dt-empty">Nenhuma data cadastrada ainda. Adicione a primeira acima.</p>';const nx=dated.find(x=>x.diff>=0);const side=nx?'<div class="au-dt-next"><span class="au-lab">Próxima data</span><div><div class="au-dt-n">'+(nx.diff===0?'Hoje':nx.diff)+'</div><div class="au-dt-nl">'+(nx.diff===0?esc(nx.name):(nx.diff===1?'dia':'dias')+' para '+esc(nx.name))+'</div></div><button type="button" class="au-dt-pri" onclick="project('+JSON.stringify(nx.raw).replace(/"/g,'&quot;')+')">Projetar agora</button></div>':'';return '<div class="au-datas"><div class="au-dt-head"><span class="au-lab">Eventos e comemorações</span><h1>Datas Especiais</h1></div><form class="au-dt-add" onsubmit="event.preventDefault();datasAddAurora()"><input id="dt-d" inputmode="numeric" maxlength="10" placeholder="dd/mm/aaaa" aria-label="Data"><input id="dt-n" placeholder="Nome do evento ou comemoração" aria-label="Nome do evento"><input id="new-datas" type="hidden"><button type="submit" class="au-dt-pri">Adicionar</button></form><div class="au-dt-grid"><section class="au-dt-list">'+html+'</section><aside class="au-dt-side">'+side+'<div class="au-dt-tip"><span class="au-lab">Dica</span><p>Datas projetadas aparecem no telão com o tema escolhido no Studio de Projeção.</p></div></aside></div></div>'}
function section(key,title,placeholder){if(key==='datas'&&document.documentElement.getAttribute('data-skin')==='aurora')return datasAurora();return '<div class="panel"><h2>'+title+'</h2><input id="new-'+key+'" placeholder="'+placeholder+'"><button onclick="addItem(\''+key+'\')">Adicionar</button>'+itemList(key)+'</div>'}
let selectedSchedule=null,editingSchedule=null;
function scheduleId(){return 'culto-'+Date.now()+'-'+Math.random().toString(36).slice(2,8)}
function ensureSchedules(){if(!Array.isArray(data.cronogramas))data.cronogramas=[];if(data.cronograma?.length){data.cronogramas.unshift({id:scheduleId(),name:'Cronograma anterior',date:'',items:[...data.cronograma]});data.cronograma=[];localStorage.setItem('iasd-studio',JSON.stringify(data))}if(!selectedSchedule&&cloudSchedules.length)selectedSchedule=cloudSchedules[0].id}
function showSchedule(id){selectedSchedule=id;editingSchedule=null;render()}
function newSchedule(){if(!canEditSchedule()){go('Mais');return}editingSchedule='new';render()}
function editSchedule(id){if(!canEditSchedule())return;editingSchedule=id;selectedSchedule=id;render()}
function cancelSchedule(){editingSchedule=null;render()}
let scheduleSaving=false;
function scheduleFeedback(message,error=true){const el=$('schedule-feedback');if(el){el.textContent=message;el.style.color=error?'#ad3441':'#227a54';el.style.display='block'}else alert(message)}
async function saveSchedule(){
 if(scheduleSaving)return;
 if(!canEditSchedule()){scheduleFeedback('Sua sessão expirou ou sua conta ainda não tem permissão. Entre novamente.');return}
 const name=$('schedule-name')?.value.trim(),date=$('schedule-date')?.value||null;
 const P=window.IASDPages;let items=P?.normSched?P.normSched($('schedule-lines')?.value||''):($('schedule-lines')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const team=P?.schTeamGet?P.schTeamGet():[];if(team.length)items.push(P.TEAM_TAG+team.join(', '));
 if(!name){scheduleFeedback('Informe o nome do culto para salvar.');$('schedule-name')?.focus();return}
 localStorage.setItem('iasd-schedule-draft',JSON.stringify({name,date,items}));scheduleFeedback('Conectando ao Supabase...',false);scheduleSaving=true;const btn=$('save-schedule-btn');if(btn){btn.disabled=true;btn.textContent='Salvando...'}
 try{
  const payload={name,service_date:date,items};
  const result=editingSchedule==='new'
   ?await cloud.from('iasd_schedules').insert({...payload,created_by:cloudUser.id}).select().single()
   :await cloud.from('iasd_schedules').update(payload).eq('id',editingSchedule).select().single();
  if(result.error)throw result.error;if(!result.data?.id)throw Error('O banco não confirmou o cadastro');
  const savedId=result.data.id;localStorage.removeItem('iasd-schedule-draft');editingSchedule=null;
  await loadCloud();selectedSchedule=savedId;render();
 }catch(err){scheduleFeedback('Não foi possível salvar no Supabase: '+(err?.message||'erro de conexão')+'. Seus dados permanecem neste formulário.');}
 finally{scheduleSaving=false;const button=$('save-schedule-btn');if(button){button.disabled=false;button.textContent='✓ Salvar cronograma'}}
}
async function deleteSchedule(id){const g=cloudSchedules.find(x=>x.id===id);if(!canDeleteSchedule()){alert('Apenas o fundador ou um administrador pode excluir cronogramas.');return}if(!g||!(await IASDDialog.confirm('Excluir todo o cronograma "'+g.name+'"? Esta ação não pode ser desfeita.')))return;const r=await cloud.from('iasd_schedules').delete().eq('id',id);if(r.error){alert('Erro ao excluir: '+r.error.message);return}await loadCloud()}
async function removeScheduleLine(i){const g=cloudSchedules.find(x=>x.id===selectedSchedule);if(!canEditSchedule()){alert('Entre com uma conta de editor ou administrador.');return}if(!g||!(await IASDDialog.confirm('Excluir esta atividade?')))return;const items=g.items.filter((_,j)=>j!==i);const r=await cloud.from('iasd_schedules').update({items}).eq('id',g.id);if(r.error){alert(r.error.message);return}await loadCloud();selectedSchedule=g.id;render()}
async function importOldSchedules(){if(!canEditSchedule())return;ensureSchedules();if(!data.cronogramas.length){alert('Nenhum cronograma antigo neste navegador.');return}if(!(await IASDDialog.confirm('Importar '+data.cronogramas.length+' cronograma(s) deste navegador para a nuvem? Confira depois se já existem cópias para evitar duplicações.')))return;const payload=data.cronogramas.map(g=>({name:g.name,service_date:g.date||null,items:g.items,created_by:cloudUser.id}));const r=await cloud.from('iasd_schedules').insert(payload);if(r.error){alert('Falha na importação: '+r.error.message);return}data.cronogramas=[];localStorage.setItem('iasd-studio',JSON.stringify(data));await loadCloud();alert('Cronogramas importados para a nuvem.')}
function scrollSchedules(direction){const el=$('schedule-strip');if(el)el.scrollBy({left:direction*Math.max(230,el.clientWidth*.72),behavior:'smooth'})}
function schedulePage(){ensureSchedules();const group=cloudSchedules.find(g=>g.id===selectedSchedule);if(!cloudReady)return '<div class="panel"><h2>Conectando à nuvem...</h2></div>';let html=(cloudMessage?'<div class="panel" role="alert" style="border:1px solid #b94a54;color:#a32d38">'+esc(cloudMessage)+'</div>':'')+'<div class="panel schedules-panel"><div class="sectionhead schedules-heading"><h2>Meus cronogramas</h2><div class="actions"><button class="scroll-arrow" onclick="scrollSchedules(-1)" aria-label="Ver cultos anteriores">‹</button><button class="scroll-arrow" onclick="scrollSchedules(1)" aria-label="Ver próximos cultos">›</button>'+(canEditSchedule()?'<button class="primary" onclick="newSchedule()">+ Novo</button>':'')+'</div></div><div id="schedule-strip" class="schedule-groups">'+cloudSchedules.map(g=>'<button class="schedule-group '+(g.id===selectedSchedule?'selected':'')+'" onclick="showSchedule(\''+g.id+'\')"><strong>'+esc(g.name)+'</strong>'+(g.date?'<small>'+esc(g.date.split('-').reverse().join('/'))+'</small>':'')+'</button>').join('')+'</div></div>'+(data.cronogramas?.length&&canEditSchedule()?'<div class="panel"><p>Existem '+data.cronogramas.length+' cronograma(s) antigos neste navegador.</p><button class="primary" onclick="importOldSchedules()">Importar para a nuvem</button></div>':'');const pgExtra=(cloudMessage?'<div class="panel" role="alert" style="border:1px solid #b94a54;color:#a32d38">'+esc(cloudMessage)+'</div>':'')+(data.cronogramas?.length&&canEditSchedule()?'<div class="panel"><p>Existem '+data.cronogramas.length+' cronograma(s) antigos neste navegador.</p><button class="primary" onclick="importOldSchedules()">Importar para a nuvem</button></div>':'');if(editingSchedule&&canEditSchedule()){const draft=editingSchedule==='new'?JSON.parse(localStorage.getItem('iasd-schedule-draft')||'null'):null;const g=editingSchedule==='new'?(draft||{name:'',date:'',items:[]}):cloudSchedules.find(x=>x.id===editingSchedule);const form=window.IASDPages?.schedForm?IASDPages.schedForm(g,editingSchedule==='new'):'<div class="panel"><h2>'+(editingSchedule==='new'?'Novo cronograma':'Editar cronograma')+'</h2><label for="schedule-name">Nome do culto</label><input id="schedule-name" placeholder="Ex.: Culto de sábado — manhã" value="'+esc(g.name)+'"><label for="schedule-date">Data (opcional)</label><input type="date" id="schedule-date" value="'+esc(g.date)+'"><label for="schedule-lines">Atividades (uma por linha)</label><textarea id="schedule-lines" rows="9" placeholder="09:00 — Abertura — Ana Paula&#10;09:15 — Louvor — Equipe de música">'+esc(g.items.join('\n'))+'</textarea><div class="actions"><button id="save-schedule-btn" class="primary" onclick="saveSchedule()">✓ Salvar cronograma</button><button onclick="cancelSchedule()">Cancelar</button></div><p id="schedule-feedback" role="alert" style="display:none;margin-top:12px;font-weight:650"></p></div>';if(window.IASDPages?.sched)return pgExtra+IASDPages.sched({group,editForm:form});html+=form;return html}if(window.IASDPages?.sched)return pgExtra+IASDPages.sched({group});if(group){html+='<div class="panel"><div class="sectionhead" style="margin:0 0 14px"><div><h2>'+esc(group.name)+'</h2>'+(group.date?'<p class="muted">'+esc(group.date.split('-').reverse().join('/'))+'</p>':'')+'</div></div><div class="actions">'+(canEditSchedule()?'<button class="primary" onclick="editSchedule(\''+group.id+'\')">✎ Editar</button>':'')+(canDeleteSchedule()?'<button class="danger-btn" onclick="deleteSchedule(\''+group.id+'\')">Excluir cronograma</button>':'')+'</div><div class="sectionhead"><h2>Programação</h2><span class="muted">'+group.items.length+' atividades</span></div>'+scheduleList(group.items,canEditSchedule())+'</div>'}else html+='<div class="panel"><h2>Nenhum cronograma ainda</h2><p class="muted">Toque em + Novo para cadastrar o primeiro culto.</p></div>';return html}
function canUseSound(){return !!cloudUser&&(window.IASDAccess?.canUseSound(cloudRole)??['sonoplasta','founder','cofounder'].includes(cloudRole))}
function soundDenied(){return '<section class="panel sound-gate" role="status"><span class="sound-gate-icon">♫</span><h2>Área exclusiva da sonoplastia</h2><p>Este setor é reservado às contas autorizadas como sonoplasta. Entre com sua conta ou solicite ao fundador a liberação de acesso.</p>'+(cloudUser?'<button class="primary" onclick="go(\'Painel\')">Voltar ao início</button>':'<button class="primary" onclick="openAuthModal()">Entrar na conta</button>')+'</section>'}
function go(t){if(t==='Sonoplastia'&&canUseSound())t='Projeção';if(['Projeção','Sorteadores'].includes(t)&&!canUseSound())t='Sonoplastia';if(t!==current){let h=[];try{h=JSON.parse(sessionStorage.getItem('iasd-nav-history')||'[]')}catch(e){}if(h[h.length-1]!==current)h.push(current);sessionStorage.setItem('iasd-nav-history',JSON.stringify(h.slice(-30)))}current=t;sessionStorage.setItem('iasd-current-page',t);window.IASDRouter?.sync?.(t);render();if(t==='Fundador'&&cloudRole==='founder')loadFounderAccounts();if(t==='Perfil'&&cloudUser)loadMyProfile();if(t==='Acervo'||(t==='Mídia'&&canManageSite()))loadImages();window.scrollTo({top:0,behavior:'smooth'})}
window.addEventListener('popstate',()=>{let page=window.IASDRouter?.pageFromLocation?.();if(page==='Sonoplastia'&&canUseSound())page='Projeção';if(['Projeção','Sorteadores'].includes(page)&&!canUseSound())page='Sonoplastia';if(page&&page!==current){current=page;sessionStorage.setItem('iasd-current-page',page);render();if(page==='Fundador'&&cloudRole==='founder')loadFounderAccounts();if(page==='Perfil'&&cloudUser)loadMyProfile();if(page==='Acervo'||(page==='Mídia'&&canManageSite()))loadImages();window.scrollTo({top:0})}});
function mobileGoBack(){let h=[];try{h=JSON.parse(sessionStorage.getItem('iasd-nav-history')||'[]')}catch(e){}let prev=h.pop();while(prev===current&&h.length)prev=h.pop();sessionStorage.setItem('iasd-nav-history',JSON.stringify(h));if(prev){current=prev;sessionStorage.setItem('iasd-current-page',prev);render();window.scrollTo({top:0,behavior:'smooth'});return}if(current!=='Painel')go('Painel')}

