let themeSearch='';let activeSiteTheme='grafite',selectedSiteTheme='grafite',previewDevice='desktop',previewLandscape=false,themeSaving=false;
function themeById(id){return SITE_THEMES.find(t=>t.id===id)||SITE_THEMES[0]}
function applySiteTheme(id){
 activeSiteTheme=id||activeSiteTheme||'grafite';
 document.documentElement.removeAttribute('data-site-theme');
 const el=$('iasd-theme-style');if(el)el.textContent='';
}
async function loadActiveTheme(){
 if(!cloud)return;
 const r=await cloud.from('iasd_site_theme').select('theme_id,layout_id').eq('id',1).maybeSingle();
 if(!r.error&&r.data){activeSiteTheme=r.data.theme_id||'grafite';selectedSiteTheme=activeSiteTheme;activeLayout='layout-01';selectedLayout='layout-01'}
 document.documentElement.removeAttribute('data-layout-structure');
 document.documentElement.removeAttribute('data-layout-variant');
 document.documentElement.removeAttribute('data-site-theme');
 const el=$('iasd-theme-style');if(el)el.textContent='';
}
window.addEventListener('message',e=>{if(e.origin!==location.origin||!e.data||e.data.type!=='IASD_THEME_PREVIEW')return;if(!new URLSearchParams(location.search).has('preview'))return;window.__previewTheme=e.data.themeId;applySiteTheme(e.data.themeId)});
function openDevicePreview(){if(cloudRole!=='founder')return;previewDevice=previewDevice||'desktop';previewLandscape=false;drawDevicePreview()}
function closeDevicePreview(){const root=$('device-preview-root');if(root)root.innerHTML='';document.body.classList.remove('preview-open')}
function selectPreviewDevice(device){previewDevice=device;drawDevicePreview()}
function rotateDevicePreview(){previewLandscape=!previewLandscape;drawDevicePreview()}
function drawDevicePreview(){if(cloudRole!=='founder')return;document.body.classList.add('preview-open');const dimensions={desktop:[1440,900],tablet:previewLandscape?[1024,768]:[768,1024],mobile:previewLandscape?[844,390]:[390,844]},[w,h]=dimensions[previewDevice],scale=Math.min(1,Math.max(250,innerWidth-90)/w,Math.max(220,innerHeight-190)/h),root=$('device-preview-root');root.innerHTML='<div class="device-preview-backdrop" onclick="closeDevicePreview()"></div><section class="device-preview-dialog clean-device-preview" role="dialog" aria-modal="true"><div class="device-preview-toolbar"><div class="preview-heading"><strong>Visualizador de dispositivos</strong><small>PC, tablet e celular.</small></div><div class="device-switch">'+[['desktop','▣ PC'],['tablet','▯ Tablet'],['mobile','▯ Mobile']].map(([d,n])=>'<button class="'+(previewDevice===d?'selected':'')+'" onclick="selectPreviewDevice(\''+d+'\')">'+n+'</button>').join('')+'</div><div class="preview-controls"><button onclick="rotateDevicePreview()" '+(previewDevice==='desktop'?'disabled':'')+'>↻ Girar</button><button onclick="closeDevicePreview()">✕</button></div></div><div class="preview-viewport"><div class="preview-frame-shell" style="width:'+(w*scale)+'px;height:'+(h*scale)+'px"><iframe id="device-preview-frame" style="width:'+w+'px;height:'+h+'px;transform:scale('+scale+');transform-origin:top left" src="'+location.pathname+'?preview=1"></iframe></div></div><div class="preview-footnote">'+w+' × '+h+' px</div></section>'}
window.addEventListener('resize',()=>{if($('device-preview-frame'))drawDevicePreview()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('device-preview-frame'))closeDevicePreview()});

const QUICK=[['Sonoplastia','♫','home_icon_projection'],['Cronograma','▦','home_icon_schedule'],['Bíblia','▤','home_icon_bible'],['Escalas','♟','home_icon_scales'],['Datas especiais','✧','home_icon_dates']];
let customTabs=[],assetFrames={},coverSlotEditing='',coverPath='',frameX=50,frameY=50,frameZoom=1;
const allQuick=()=>[...QUICK,...customTabs.map(t=>['custom:'+t.id,t.icon,'custom_cover_'+t.id])];
const tabName=t=>t.startsWith('custom:')?(customTabs.find(x=>x.id===t.slice(7))?.title||'Aba'):t;
const tabDesc=t=>customTabs.find(x=>'custom:'+x.id===t)?.description||({Projeção:'Controle a segunda tela',Cronograma:'Horários e responsáveis',Bíblia:'Versículos e projeção',Escalas:'Equipe e escalas',Mídia:'Hinos e apresentações',Sorteadores:'Sorteio de pessoas e números','Datas especiais':'Datas da igreja',Mais:'Outras ferramentas'})[t]||'';
function quickCard([t,icon,slot]){const p=siteAssets[slot],f=assetFrames[slot]||{},media=p?(/\.(mp4|webm|mov)$/i.test(p)?'<video autoplay muted loop playsinline src="'+esc(imageUrl(p))+'"></video>':'<img class="quick-backdrop" src="'+esc(imageUrl(p))+'" alt="" aria-hidden="true"><img class="quick-foreground" src="'+esc(imageUrl(p))+'" style="'+quickFrameStyle(f.position_x??50,f.position_y??50,f.zoom??1)+'" alt="">'):'<span>'+esc(icon)+'</span>';return '<article class="quick-card"><button class="quick-link" onclick="go('+JSON.stringify(t).replace(/"/g,'&quot;')+')"><div class="quick-cover">'+media+'</div><small>'+esc(tabDesc(t))+'</small><b>ABRIR ↗</b></button>'+(canManageSite()?'<span class="quick-admin-title">'+esc(tabName(t))+'</span><button class="quick-edit" onclick="editCover('+JSON.stringify(slot).replace(/"/g,'&quot;')+')">✎ Editar capa</button>':'')+'</article>'}
function filterHomeQuick(query){const v=(query||'').toLowerCase();document.querySelectorAll('#home-quick-track .quick-card').forEach(c=>c.style.display=c.textContent.toLowerCase().includes(v)?'':'none')}
function scrollQuick(direction){const el=document.getElementById('home-quick-track');if(el)el.scrollBy({left:direction*Math.max(300,el.clientWidth*.72),behavior:'smooth'})}
function quickHome(){let a=allQuick();if(cloudRole==='founder')a.push(['Fundador','♛','home_icon_founder']);if(canManageSite())a.push(['Acervo','▧','home_icon_gallery']);return '<section class="quick-section"><div class="sectionhead"><h2>Acesso rápido</h2>'+(canManageTabs()?'<button class="quick-add" onclick="newTab()">＋ Criar aba</button>':'')+'</div><div class="quick-carousel"><button class="quick-arrow quick-arrow-prev" onclick="scrollQuick(-1)" aria-label="Ver acessos anteriores">‹</button><div class="quick-track" id="home-quick-track">'+a.map(quickCard).join('')+'</div><button class="quick-arrow quick-arrow-next" onclick="scrollQuick(1)" aria-label="Ver mais acessos">›</button></div></section>'}
async function loadCustomTabs(){if(!cloud)return;const r=await cloud.from('iasd_custom_tabs').select('*').order('sort_order');if(!r.error){customTabs=r.data||[];render()}}
async function loadAssetFrames(){if(!cloud)return;const r=await cloud.from('iasd_asset_framing').select('*');if(!r.error){assetFrames=Object.fromEntries((r.data||[]).map(x=>[x.slot,x]));render()}}
function newTab(){if(!canManageTabs())return;const root=$('inline-editor-root');root.innerHTML='<div class="iasd-edit-backdrop" onclick="closeInlineTextEditor()"></div><section class="iasd-edit-dialog" role="dialog" aria-modal="true"><div class="iasd-edit-head"><strong>Criar aba</strong><button onclick="closeInlineTextEditor()">✕</button></div><p>A nova aba aparecerá no menu e no acesso rápido.</p><label>Nome</label><input id="new-tab-name" maxlength="70" placeholder="Ex.: Louvor"><label>Descrição</label><input id="new-tab-desc" maxlength="180"><label>Ícone</label><input id="new-tab-icon" maxlength="3" value="✦"><p id="new-tab-status"></p><button class="primary" onclick="createTab()">Criar aba</button></section>'}
async function createTab(){const title=$('new-tab-name')?.value.trim(),description=$('new-tab-desc')?.value.trim()||'',icon=$('new-tab-icon')?.value.trim()||'✦';if(!title){$('new-tab-status').textContent='Informe o nome.';return}const r=await cloud.from('iasd_custom_tabs').insert({title,description,icon,sort_order:100+customTabs.length}).select().single();if(r.error){$('new-tab-status').textContent=r.error.message;return}customTabs.push(r.data);closeInlineTextEditor();go('custom:'+r.data.id)}
function customPage(id){const t=customTabs.find(x=>x.id===id);if(!t)return '<div class="panel">Aba não encontrada.</div>';if(window.IASDHinario&&String(t.title||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase()==='hinario')return IASDHinario.page()+(canManageTabs()?'<div class="panel" style="margin-top:14px"><button onclick="renameTab('+JSON.stringify(id).replace(/"/g,'&quot;')+')">Editar aba</button> <button onclick="removeTab('+JSON.stringify(id).replace(/"/g,'&quot;')+')">Excluir aba</button></div>':'');return '<div class="panel"><h2>'+esc(t.icon)+' '+esc(t.title)+'</h2><p>'+esc(t.description||'Página personalizada.')+'</p>'+(canManageSite()?'<button onclick="editCover('+JSON.stringify('custom_cover_'+id).replace(/"/g,'&quot;')+')">✎ Editar capa</button>'+(canManageTabs()?'<button onclick="renameTab('+JSON.stringify(id).replace(/"/g,'&quot;')+')">Editar aba</button><button onclick="removeTab('+JSON.stringify(id).replace(/"/g,'&quot;')+')">Excluir aba</button>':'')+'':'')+'</div>'}
async function renameTab(id){const t=customTabs.find(x=>x.id===id);if(!t||!canManageTabs())return;const title=(await IASDDialog.prompt('Nome da aba:',t.title));if(!title?.trim())return;const description=(await IASDDialog.prompt('Descrição:',t.description||''));if(description===null)return;const r=await cloud.from('iasd_custom_tabs').update({title:title.trim(),description:description.trim()}).eq('id',id);if(r.error)alert(r.error.message);else loadCustomTabs()}
async function removeTab(id){if(!canManageTabs()||!(await IASDDialog.confirm('Excluir esta aba?')))return;const r=await cloud.from('iasd_custom_tabs').delete().eq('id',id);if(r.error)alert(r.error.message);else{customTabs=customTabs.filter(t=>t.id!==id);go('Painel')}}
function editCover(slot){if(!canManageSite())return;coverSlotEditing=slot;coverPath=siteAssets[slot]||'';const f=assetFrames[slot]||{};frameX=Number(f.position_x??50);frameY=Number(f.position_y??50);frameZoom=Number(f.zoom??1);drawCover();loadCoverGallery()}
function closeCover(){coverSlotEditing='';$('inline-editor-root').innerHTML=''}
function coverImageStyle(x,y,z){const size=130*Math.max(1,Number(z)||1);return 'position:absolute;width:'+size+'%;height:'+size+'%;max-width:none;left:'+((100-size)*Number(x)/100)+'%;top:'+((100-size)*Number(y)/100)+'%;object-fit:cover;object-position:'+Number(x)+'% '+Number(y)+'%;transform:none'}
function quickFrameStyle(x,y,z){const dx=(50-Number(x))*.9,dy=(50-Number(y))*.9;return 'object-position:center;transform:translate('+dx+'%,'+dy+'%) scale('+Math.max(1,Number(z)||1)+')'}
function drawCover(){if(!coverSlotEditing)return;const slot=coverSlotEditing;const isBanner=slot==='home_banner'||slot.startsWith('home_banner_');const isQuick=!isBanner&&slot!=='site_logo';const media=coverPath?(isQuick?'<img class="quick-backdrop" src="'+esc(imageUrl(coverPath))+'" alt="" aria-hidden="true"><img id="cover-img" class="quick-foreground" src="'+esc(imageUrl(coverPath))+'" style="'+quickFrameStyle(frameX,frameY,frameZoom)+'" alt="Prévia">':'<img id="cover-img" src="'+esc(imageUrl(coverPath))+'" style="'+coverImageStyle(frameX,frameY,frameZoom)+'" alt="Prévia">'):'<span>Escolha ou importe uma imagem.</span>';$('inline-editor-root').innerHTML='<div class="iasd-edit-backdrop" onclick="closeCover()"></div><section class="cover-dialog" role="dialog" aria-modal="true"><header class="cover-head"><strong>✎ '+((slot==='home_banner'||slot.startsWith('home_banner_'))?'Imagem do carrossel da página inicial':slot==='site_logo'?'Logotipo':'Capa do acesso rápido')+'</strong><button onclick="closeCover()">✕</button></header><div class="cover-body"><div><div class="cover-preview '+((slot==='home_banner'||slot.startsWith('home_banner_'))?'wide':slot==='site_logo'?'logo':'portrait')+'">'+media+'</div><p>A imagem começa inteira (9:16). Ajuste o zoom e arraste para enquadrar, se desejar.</p><label>Zoom <input type="range" min="1" max="3" step=".05" value="'+frameZoom+'" oninput="coverFrame(\'z\',this.value)"></label><label>Horizontal <input type="range" min="0" max="100" value="'+frameX+'" oninput="coverFrame(\'x\',this.value)"></label><label>Vertical <input type="range" min="0" max="100" value="'+frameY+'" oninput="coverFrame(\'y\',this.value)"></label><button onclick="frameX=50;frameY=50;frameZoom=1;updateCover()">Centralizar</button></div><div><div class="cover-gallery-head"><h3>Galeria do site</h3><label>＋ Importar imagem<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden onchange="importCover(this)"></label></div><div id="cover-gallery" class="cover-gallery">Carregando...</div></div></div><footer class="cover-footer"><span id="cover-status"></span>'+((slot==='home_banner'||slot.startsWith('home_banner_'))?'<button onclick="editHomeCarousel()">‹ Voltar ao carrossel</button>':'')+'<button onclick="closeCover()">Cancelar</button>'+(siteAssets[slot]?'<button onclick="removeCover()">Remover imagem</button>':'')+'<button class="primary" onclick="saveCover()">Salvar e publicar</button></footer></section>';const el=$('inline-editor-root').querySelector('.cover-preview');let drag=false,x,y,fx,fy;el.onpointerdown=e=>{if(!coverPath)return;drag=true;x=e.clientX;y=e.clientY;fx=frameX;fy=frameY;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag)return;frameX=Math.max(0,Math.min(100,fx+(x-e.clientX)/el.clientWidth*100));frameY=Math.max(0,Math.min(100,fy+(y-e.clientY)/el.clientHeight*100));updateCover()};el.onpointerup=()=>drag=false;el.onpointercancel=()=>drag=false}
function updateCover(){const img=$('cover-img');if(img){img.style.cssText=(coverSlotEditing==='home_banner'||coverSlotEditing.startsWith('home_banner_')||coverSlotEditing==='site_logo')?coverImageStyle(frameX,frameY,frameZoom):quickFrameStyle(frameX,frameY,frameZoom)}const ranges=$('inline-editor-root').querySelectorAll('.cover-body input[type=range]');if(ranges.length===3){ranges[0].value=frameZoom;ranges[1].value=frameX;ranges[2].value=frameY}}
function coverFrame(k,v){if(k==='z')frameZoom=Number(v);if(k==='x')frameX=Number(v);if(k==='y')frameY=Number(v);updateCover()}
async function loadCoverGallery(){
 const slot=coverSlotEditing;if(!slot)return;
 const gallery=$('cover-gallery');if(!gallery)return;
 gallery.textContent='Carregando imagens da biblioteca...';
 try{
  // A biblioteca administrativa e o editor consultam os mesmos arquivos do Storage.
  // A RPC evita respostas vazias do endpoint de listagem do Storage.
  const result=await cloud.rpc('iasd_list_site_images');
  if(result.error)throw result.error;
  const all=(result.data||[]).map(x=>x.name).filter(Boolean);
  const el=$('cover-gallery');if(!el||coverSlotEditing!==slot)return;
  el.innerHTML=all.length?all.map(path=>'<button class="'+(coverPath===path?'selected':'')+'" onclick="chooseCover('+JSON.stringify(path).replace(/"/g,'&quot;')+')"><img loading="lazy" src="'+esc(imageUrl(path))+'" alt="'+esc(path)+'"></button>').join(''):'Nenhuma imagem encontrada na biblioteca do site.';
 }catch(e){
  const el=$('cover-gallery');if(el&&coverSlotEditing===slot)el.textContent='Não foi possível carregar a biblioteca: '+(e.message||String(e));
 }
}
function chooseCover(path){coverPath=path;frameX=50;frameY=50;frameZoom=1;drawCover();loadCoverGallery()}
async function importCover(input){const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>50*1024*1024){$('cover-status').textContent='Imagem inválida ou maior que 50 MB.';return}$('cover-status').textContent='Importando...';const path=crypto.randomUUID()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,60);const r=await cloud.storage.from(IMAGE_BUCKET).upload(path,file,{contentType:file.type});if(r.error){$('cover-status').textContent=r.error.message;return}chooseCover(path)}
async function saveCover(){if(!coverSlotEditing||!coverPath){$('cover-status').textContent='Escolha uma imagem.';return}const slot=coverSlotEditing;$('cover-status').textContent='Publicando...';const r=await cloud.from('iasd_site_assets').upsert({slot,image_path:coverPath,updated_at:new Date().toISOString()});if(r.error){$('cover-status').textContent=r.error.message;return}siteAssets[slot]=coverPath;const frame={slot,position_x:Math.round(frameX),position_y:Math.round(frameY),zoom:frameZoom};const q=await cloud.from('iasd_asset_framing').upsert(frame);if(q.error){$('cover-status').textContent=q.error.message;return}assetFrames[slot]=frame;closeCover();render()}
async function removeCover(){if(!coverSlotEditing||!(await IASDDialog.confirm('Remover a imagem desta capa?')))return;const slot=coverSlotEditing,r=await cloud.from('iasd_site_assets').delete().eq('slot',slot);if(r.error){$('cover-status').textContent=r.error.message;return}delete siteAssets[slot];closeCover();render()}

function tile(t,sub,glyph,color,featured){const slot=({'Projeção':'home_icon_projection','Cronograma':'home_icon_schedule','Bíblia':'home_icon_bible','Mídia':'home_icon_media','Mais':'home_icon_more'})[t];return '<button class="tile '+(featured?'feature':'')+'" onclick="go(\''+t+'\')"><span class="glyph">'+glyph+'</span><strong>'+t+'</strong><small>'+sub+'</small><span class="tile-arrow">›</span></button>'}
/* Edição contextual de textos: somente fundador e administrador */
const DEFAULT_EDITABLE_TEXT={
'Painel':[['.hero .eyebrow','Boas-vindas'],['.hero h2','Título principal'],['.hero p','Descrição principal'],['.verse-card blockquote','Texto de destaque'],['.verse-card small','Referência bíblica']],
'Projeção':[['.sectionhead h2','Título da página'],['.panel h2','Título da prévia'],['.panel .muted','Instruções da projeção']],
'Escalas':[['.sectionhead h2','Título das escalas']],
'Datas especiais':[['.sectionhead h2','Título das datas']],
'Sorteadores':[['.panel h2','Título da ferramenta']],
'Mídia':[['.panel h2','Título da biblioteca']],
'Mais':[['.sectionhead h2','Título das ferramentas']]
};
let siteTextOverrides={},siteTextBusy=false;
async function loadSiteText(){if(!cloud)return;const r=await cloud.from('iasd_site_content').select('content_key,content_value');if(!r.error){siteTextOverrides=Object.fromEntries((r.data||[]).map(x=>[x.content_key,x.content_value]));applyPalette(siteTextOverrides.site_palette||'aurora');render()}}
function contentEditAllowed(){return !!cloudUser&&(window.IASDAccess?.canEditTexts(cloudRole)??['founder','cofounder','admin'].includes(cloudRole))}
function applyInlineEditors(){const root=$('content');if(!root)return;
 const eligiblePages=['Painel','Projeção','Sorteadores','Mais','Mídia'];if(!eligiblePages.includes(current))return;
 const targets=[];
 if(current==='Painel'){
  targets.push(...[['.hero .eyebrow','Boas-vindas'],['.hero h2','Título principal'],['.hero p','Descrição principal'],['.verse-card blockquote','Versículo em destaque'],['.verse-card small','Referência bíblica']].map(([selector,label],i)=>({el:root.querySelector(selector),key:'home_static_'+i,label})));
  root.querySelectorAll('.tile').forEach((tile,i)=>{targets.push({el:tile.querySelector('strong'),key:'home_tile_'+i+'_title',label:'Nome do cartão'});targets.push({el:tile.querySelector('small'),key:'home_tile_'+i+'_desc',label:'Descrição do cartão'})});
 }else if(current==='Projeção'){
  root.querySelectorAll('.sectionhead h2,.panel h2,.panel>p.muted').forEach((el,i)=>targets.push({el,key:'projection_'+i,label:'Texto da projeção'}));
 }else if(current==='Sorteadores'){
  root.querySelectorAll('.panel h2,.panel h3').forEach((el,i)=>targets.push({el,key:'draw_'+i,label:'Título da ferramenta'}));
 }else if(current==='Mais'){
  root.querySelectorAll('.sectionhead h2,.grid .tile strong,.grid .tile small').forEach((el,i)=>targets.push({el,key:'more_'+i,label:'Texto da ferramenta'}));
 }else if(current==='Mídia'){
  root.querySelectorAll('.panel h2,.panel>p:not(.muted)').forEach((el,i)=>targets.push({el,key:'media_'+i,label:'Texto da biblioteca'}));
 }
 for(const item of targets){if(!item.el)continue;const {el,key,label}=item;if(!el.dataset.iasdDefault)el.dataset.iasdDefault=el.textContent.trim();if(Object.prototype.hasOwnProperty.call(siteTextOverrides,key))el.textContent=siteTextOverrides[key];if(!contentEditAllowed())continue;el.classList.add('iasd-editable-text');const btn=document.createElement('button');btn.className='iasd-pencil';btn.type='button';btn.textContent='✎';btn.title='Editar '+label;btn.setAttribute('aria-label','Editar '+label);btn.onclick=e=>{e.stopPropagation();e.preventDefault();openInlineTextEditor(key,label,el.dataset.iasdDefault,el.textContent.replace('✎','').trim())};el.appendChild(btn)}
}
function openInlineTextEditor(key,label,original,value){if(!contentEditAllowed())return;const root=$('inline-editor-root');root.innerHTML='<div class="iasd-edit-backdrop" onclick="closeInlineTextEditor()"></div><div class="iasd-edit-dialog" role="dialog" aria-modal="true" aria-label="Editar conteúdo"><div class="iasd-edit-head"><strong>✎ '+esc(label)+'</strong><button onclick="closeInlineTextEditor()" aria-label="Fechar">✕</button></div><p>Altere este texto. A mudança será exibida para todos após salvar.</p><textarea id="iasd-edit-value" rows="4" maxlength="1000">'+esc(value)+'</textarea><p id="iasd-edit-feedback" role="alert"></p><div class="iasd-edit-actions"><button onclick="closeInlineTextEditor()">Cancelar</button><button onclick="resetInlineText('+JSON.stringify(key).replace(/"/g,'&quot;')+')">Restaurar original</button><button id="iasd-edit-save" class="primary" onclick="saveInlineText('+JSON.stringify(key).replace(/"/g,'&quot;')+')">Salvar alterações</button></div></div>';root.dataset.original=original;$('iasd-edit-value').focus()}
function closeInlineTextEditor(){$('inline-editor-root').innerHTML=''}
async function saveInlineText(key){if(!contentEditAllowed()||siteTextBusy)return;const value=$('iasd-edit-value').value.trim();if(!value){$('iasd-edit-feedback').textContent='O campo não pode ficar vazio.';return}siteTextBusy=true;$('iasd-edit-save').disabled=true;const r=await cloud.from('iasd_site_content').upsert({content_key:key,content_value:value,updated_by:cloudUser.id,updated_at:new Date().toISOString()});siteTextBusy=false;if(r.error){$('iasd-edit-feedback').textContent='Falha ao salvar: '+r.error.message;$('iasd-edit-save').disabled=false;return}siteTextOverrides[key]=value;closeInlineTextEditor();render()}
async function resetInlineText(key){if(!contentEditAllowed()||siteTextBusy)return;siteTextBusy=true;const r=await cloud.from('iasd_site_content').delete().eq('content_key',key);siteTextBusy=false;if(r.error){$('iasd-edit-feedback').textContent=r.error.message;return}delete siteTextOverrides[key];closeInlineTextEditor();render()}


// Preferência visual individual, independente do login.
function applyTheme(mode){
 const dark=mode==='dark';
 document.documentElement.setAttribute('data-theme',dark?'dark':'light');
 try{const sf=document.getElementById('iasd-studio-frame');if(sf&&sf.contentWindow)sf.contentWindow.postMessage({type:'iasd-theme',mode:dark?'dark':'light'},location.origin)}catch(e){}
 const btn=document.getElementById('theme-toggle');
 const icon=document.getElementById('theme-icon');
 const label=document.getElementById('theme-label');
 if(icon)icon.textContent=dark?'☀':'☾';
 if(label)label.textContent=dark?'Claro':'Escuro';
 if(btn){btn.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo escuro');btn.title=dark?'Ativar modo claro':'Ativar modo escuro';btn.setAttribute('aria-pressed',String(dark))}
}
function toggleTheme(){
 const next=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';
 try{localStorage.setItem('iasd-app-theme',next)}catch(e){}
 applyTheme(next);
}
try{applyTheme(storedMode()||defaultMode())}catch(e){applyTheme('dark')}


const LAYOUT_STRUCTURES=['Clássico amplo','Menu superior','Barra de ícones','Menu à direita','Painel executivo','Compacto','Editorial central','Minimalista','Vitrine ampla','Menu de aplicativos'];
const LAYOUT_VARIANTS=['Orgânico','Arquitetônico','Editorial','Essencial','Digital'];
let activeLayout='layout-01',selectedLayout='layout-01',layoutDevice='desktop',layoutFilter='',layoutSaving=false;
function layoutNumber(id){const n=Number(String(id||'').replace('layout-',''));return Number.isInteger(n)&&n>=1&&n<=50?n:1}
function applyLayout(id){const n=layoutNumber(id);activeLayout='layout-'+String(n).padStart(2,'0');document.documentElement.dataset.layoutStructure=String(Math.ceil(n/5));document.documentElement.dataset.layoutVariant=String((n-1)%5+1)}
function layoutPreviewSend(){const frame=document.getElementById('layout-preview-frame');if(frame?.contentWindow){frame.contentWindow.postMessage({type:'IASD_LAYOUT_PREVIEW',layoutId:selectedLayout},location.origin);frame.contentWindow.postMessage({type:'IASD_THEME_PREVIEW',themeId:selectedSiteTheme},location.origin)}}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='IASD_LAYOUT_PREVIEW'||!new URLSearchParams(location.search).has('preview'))return;applyLayout(e.data.layoutId)});
function openLayoutStudio(){if(cloudRole!=='founder')return;selectedLayout=activeLayout;layoutDevice=previewDevice;layoutFilter='';drawLayoutStudio()}
function closeLayoutStudio(){document.getElementById('device-preview-root').innerHTML='';document.body.classList.remove('preview-open')}
function selectLayout(id){selectedLayout=id;document.querySelectorAll('.layout-choice').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));layoutPreviewSend();const status=document.getElementById('layout-status');if(status)status.textContent='Prévia: '+LAYOUT_STRUCTURES[Math.floor((layoutNumber(id)-1)/5)]+' · '+LAYOUT_VARIANTS[(layoutNumber(id)-1)%5]}
function filterLayouts(value){layoutFilter=value.toLowerCase();document.querySelectorAll('.layout-choice').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(layoutFilter))}
function selectLayoutDevice(device){layoutDevice=device;drawLayoutStudio()}
async function publishLayout(){if(cloudRole!=='founder'||layoutSaving)return;layoutSaving=true;const btn=document.getElementById('layout-publish');if(btn){btn.disabled=true;btn.textContent='Publicando...'}const r=await cloud.from('iasd_site_theme').update({layout_id:selectedLayout,updated_at:new Date().toISOString(),updated_by:cloudUser.id}).eq('id',1).select('layout_id').single();layoutSaving=false;if(r.error){if(btn){btn.disabled=false;btn.textContent='Publicar layout'}const status=document.getElementById('layout-status');if(status)status.textContent='Erro: '+r.error.message;return}applyLayout(r.data.layout_id);const status=document.getElementById('layout-status');if(status)status.textContent='✓ Layout publicado para todos.';if(btn){btn.disabled=false;btn.textContent='Publicado'}}
function drawLayoutStudio(){if(cloudRole!=='founder')return;document.body.classList.add('preview-open');const root=document.getElementById('device-preview-root');const sizes={desktop:[1440,900],tablet:[768,1024],mobile:[390,844]};const [w,h]=sizes[layoutDevice];const availableW=Math.max(260,innerWidth-(innerWidth<=800?36:470)),availableH=Math.max(170,innerHeight-(innerWidth<=800?460:240));const scale=Math.min(1,availableW/w,availableH/h);const cards=Array.from({length:50},(_,i)=>{const n=i+1,id='layout-'+String(n).padStart(2,'0'),structure=Math.floor(i/5),variant=i%5;const palettes=['#1b3758','#164c5d','#33415a','#263d43','#493c50'];return '<button class="layout-choice '+(id===selectedLayout?'selected':'')+'" data-id="'+id+'" onclick="selectLayout(\''+id+'\')"><span class="layout-mini" data-structure="'+(structure+1)+'" style="--mini-bg:'+palettes[variant]+';--mini-accent:#e4c081"><i></i><i></i><i></i><i></i><i></i><i></i></span><strong>'+String(n).padStart(2,'0')+' · '+LAYOUT_STRUCTURES[structure]+'</strong><small>'+LAYOUT_VARIANTS[variant]+'</small></button>'}).join('');root.innerHTML='<div class="layout-overlay" onclick="closeLayoutStudio()"></div><section class="layout-dialog" role="dialog" aria-modal="true" aria-label="Estúdio de layouts"><div class="layout-top"><div><h2>Estúdio de aparência</h2><p>Temas, layouts e visualização responsiva no mesmo lugar.</p><div class="studio-switch"><button onclick="openDevicePreview()">◈ Temas e dispositivos</button><button class="selected" type="button">▦ 50 layouts</button></div></div><button onclick="closeLayoutStudio()">✕ Fechar</button></div><div class="layout-body"><div class="layout-picker"><input id="layout-filter" placeholder="Buscar entre 50 templates..." oninput="filterLayouts(this.value)" value="'+layoutFilter+'"><div class="layout-cards">'+cards+'</div></div><div class="layout-preview-area"><div class="layout-device"><strong style="margin-right:auto">Prévia real do site</strong>'+['desktop','tablet','mobile'].map((d,i)=>'<button class="'+(layoutDevice===d?'selected':'')+'" onclick="selectLayoutDevice(\''+d+'\')">'+['▣ PC','▯ Tablet','▯ Celular'][i]+'</button>').join('')+'</div><div class="layout-frame-wrap"><div class="layout-frame-shell" style="width:'+(w*scale+12)+'px;height:'+(h*scale+12)+'px"><iframe id="layout-preview-frame" title="Prévia do layout" style="width:'+w+'px;height:'+h+'px;transform:scale('+scale+');transform-origin:top left" src="'+location.pathname+'?preview=1" onload="layoutPreviewSend()"></iframe></div></div></div></div><div class="layout-bottom"><span class="layout-status" id="layout-status">Selecione um template para visualizar.</span><button onclick="closeLayoutStudio()">Cancelar</button><button id="layout-publish" class="publish" onclick="publishLayout()">Publicar layout</button></div></section>';if(layoutFilter)filterLayouts(layoutFilter)}

function positionDashboardAccount(){
 const actions=document.querySelector('body > header .header-actions, #dashboard-account-slot .header-actions');
 const header=document.querySelector('body > header');
 const slot=document.getElementById('dashboard-account-slot');
 if(!actions||!header)return;
 if(current==='Painel'&&slot&&window.matchMedia('(min-width:901px)').matches){
  slot.appendChild(actions);
 }else{
  header.appendChild(actions);
 }
}
window.addEventListener('resize',positionDashboardAccount);

// A próxima cena é um rascunho local: nunca é enviada ao telão antes do comando Projetar.
let projectionNextContent='';
let projectionDraft='';
try{projectionDraft=sessionStorage.getItem('iasd-projection-draft')||''}catch(e){}
function projectionPreviewText(value){
 const t=String(value||'');
 if(t.startsWith('IASD_LYRIC:')){try{return JSON.parse(t.slice(11)).text||''}catch(e){return 'Letra do hino'}}
 if(t.startsWith('IASD_BIBLE:')){try{const b=JSON.parse(t.slice(11));return (b.ref||'Passagem bíblica')+'\\n\\n'+(b.text||'')}catch(e){return 'Passagem bíblica'}}
 if(t.startsWith('IASD_IMAGE:'))return 'Imagem projetada';
 return t||'TELA PRETA';
}
function updateProjectionConsole(){
 const live=document.getElementById('projection-live-preview');if(live)live.textContent=projectionPreviewText(data.stage);
 const next=document.getElementById('projection-next-preview');if(next)next.textContent=projectionNextContent?projectionPreviewText(projectionNextContent):'Selecione uma passagem ou mídia para a próxima projeção';
 const status=document.getElementById('projection-connection');if(status)status.textContent=companionToken?'IASD Projetor pareado':canReachProjection()?'Janela de projeção aberta':'Aguardando conexão';
}
function prepareProjection(value){projectionDraft=String(value??'');try{sessionStorage.setItem('iasd-projection-draft',projectionDraft)}catch(e){}updateProjectionConsole()}
function presentProjectionDraft(){if(!projectionDraft.trim()){projectionFeedback('Prepare um conteúdo antes de projetar.',true);return}project(projectionDraft);updateProjectionConsole()}
function projectionBlackout(){project('');updateProjectionConsole()}
function projectionRestore(){if(!projectionDraft.trim()){projectionFeedback('Prepare um conteúdo para restaurar a projeção.',true);return}presentProjectionDraft()}


const PEC_KEY='iasd-palavra-em-cena';
function pecPage(){return window.IASDJogral?IASDJogral.page():pecPageOld()}
function pecPageOld(){let saved={};try{saved=JSON.parse(localStorage.getItem(PEC_KEY)||'{}')}catch{}const field=(id,label,value,type='text')=>'<div class="pec-field"><label for="pec-'+id+'">'+label+'</label>'+(type==='textarea'?'<textarea id="pec-'+id+'">'+esc(value)+'</textarea>':type==='select'?'<select id="pec-'+id+'">'+value.map(v=>'<option>'+esc(v)+'</option>').join('')+'</select>':'<input id="pec-'+id+'" type="'+type+'" value="'+esc(value)+'">')+'</div>';return '<div class="pec-wrap"><div class="pec-hero"><div class="pec-kicker">✦ CRIATIVIDADE A SERVIÇO DA FÉ</div><h1>Palavra em Cena</h1><p>Prepare jograis para os cultos, distribua as falas e edite o roteiro antes de apresentar.</p></div><div class="pec-card"><h2>Monte sua apresentação</h2><div class="pec-grid">'+field('tema','Tema','A volta de Jesus')+field('ocasiao','Ocasião',['Culto de sábado','Culto jovem','Dia das Mães','Dia dos Pais','Semana de oração','Programa especial'],'select')+field('pessoas','Participantes','6','number')+field('duracao','Duração',['3 minutos','5 minutos','8 minutos','10 minutos','15 minutos'],'select')+field('estilo','Estilo',['Emocionante','Infantil','Jovem e dinâmico','Solene e reverente'],'select')+field('referencia','Referência bíblica (opcional)','João 14:1–3')+'</div><div class="pec-actions"><button class="primary" id="pec-ai-button" onclick="pecGenerateAI()">✦ Gerar com IA grátis</button><button onclick="pecCreate()">Criar modelo sem IA</button></div><p class="pec-hint">A IA usa o plano gratuito do Gemini, sujeito a limites. Entre na sua conta para gerar. As referências bíblicas devem ser conferidas antes da apresentação.</p></div><div class="pec-card pec-result"><h2>Seu jogral</h2><p class="muted">Edite as falas livremente e salve seu trabalho neste dispositivo.</p><textarea id="pec-text" aria-label="Texto do jogral" placeholder="Seu roteiro aparecerá aqui...">'+esc(saved.text||'')+'</textarea><div class="pec-actions"><button class="primary" onclick="pecSave()">Salvar roteiro</button><button onclick="pecCopy()">Copiar texto</button><button onclick="pecPrint()">Imprimir / PDF</button></div><p id="pec-status" class="pec-hint" role="status"></p></div></div>'}
async function pecGenerateAI(){const button=document.getElementById('pec-ai-button'),status=document.getElementById('pec-status');if(!cloudUser){alert('Entre na sua conta para gerar jograis com IA.');openAuthModal();return}const v=id=>document.getElementById('pec-'+id)?.value.trim()||'';const payload={tema:v('tema'),ocasiao:v('ocasiao'),pessoas:Number(v('pessoas')),duracao:v('duracao'),estilo:v('estilo'),referencia:v('referencia')};if(!payload.tema||payload.pessoas<2||payload.pessoas>30)return alert('Informe o tema e de 2 a 30 participantes.');button.disabled=true;button.textContent='✦ Criando seu jogral…';status.textContent='A IA está preparando as falas. Aguarde alguns segundos.';try{const session=await cloud.auth.getSession();if(!session.data.session?.access_token)throw Error('Entre novamente na sua conta.');const response=await fetch('/api/gerar-jogral',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.data.session.access_token},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível gerar o roteiro.');document.getElementById('pec-text').value=result.text;status.textContent='Jogral criado! Revise as falas e confira as referências bíblicas antes do culto.'}catch(e){status.textContent='Erro: '+e.message}finally{button.disabled=false;button.textContent='✦ Gerar com IA grátis'}}
function pecCreate(){const v=id=>document.getElementById('pec-'+id)?.value.trim()||'';const tema=v('tema')||'A esperança em Jesus',n=Math.max(2,Math.min(30,Number(v('pessoas'))||6)),ref=v('referencia'),oc=v('ocasiao'),est=v('estilo'),dur=v('duracao');const lines=['JOGRAL — '+tema.toUpperCase(),'Ocasião: '+oc+' | Participantes: '+n+' | Duração desejada: '+dur+' | Estilo: '+est,'','[INÍCIO — música instrumental suave. Os participantes formam um semicírculo.]',''];const phrases=['Hoje nos reunimos para anunciar uma esperança que não se apaga.','Mesmo quando os dias são difíceis, a fé nos lembra que não caminhamos sozinhos.','A Palavra de Deus nos convida a olhar além das circunstâncias.','Nossa esperança não está no que vemos, mas naquele em quem confiamos.','Cada promessa do Senhor é um convite à coragem e à perseverança.','Que nossa voz anuncie o amor de Cristo àqueles que precisam de esperança.'];for(let i=0;i<n;i++)lines.push('PARTICIPANTE '+(i+1)+': '+phrases[i%phrases.length]);lines.push('','TODOS: Nossa esperança está em Jesus!','',ref?'[LEITURA BÍBLICA — conferir o texto na Bíblia antes da apresentação: '+ref+']':'[LEITURA BÍBLICA — escolha e confira uma passagem adequada ao tema.]','','[PAUSA — música instrumental; todos olham para a congregação.]','');for(let i=0;i<n;i++)lines.push('PARTICIPANTE '+(i+1)+': '+['Que nossa fé se transforme em amor.','Que nossa espera seja acompanhada de serviço.','Que nossas palavras transmitam paz.','Que nossa igreja permaneça unida.','Que cada família encontre consolo em Cristo.','E que todos estejamos preparados para o encontro com o Senhor.'][i%6]);lines.push('','TODOS (com firmeza): Até aquele grande dia, permaneceremos firmes na esperança!','','[ENCERRAMENTO — breve silêncio; a música diminui gradualmente.]');document.getElementById('pec-text').value=lines.join('\n');document.getElementById('pec-status').textContent='Estrutura criada. Personalize as falas para o tema e ajuste a duração antes de apresentar.'}
function pecSave(){const text=document.getElementById('pec-text')?.value||'';try{localStorage.setItem(PEC_KEY,JSON.stringify({text,updatedAt:new Date().toISOString()}));document.getElementById('pec-status').textContent='Roteiro salvo neste dispositivo.'}catch(e){document.getElementById('pec-status').textContent='Não foi possível salvar: '+e.message}}
async function pecCopy(){try{await navigator.clipboard.writeText(document.getElementById('pec-text')?.value||'');document.getElementById('pec-status').textContent='Roteiro copiado.'}catch(e){document.getElementById('pec-status').textContent='Não foi possível copiar: '+e.message}}
function pecPrint(){const text=document.getElementById('pec-text')?.value||'';if(!text.trim())return alert('Crie ou escreva um roteiro antes de imprimir.');const w=window.open('','_blank');if(!w)return alert('Permita a janela de impressão neste navegador.');w.document.write('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Palavra em Cena — Jogral</title><style>body{font:16px/1.65 Georgia,serif;max-width:780px;margin:40px auto;padding:20px;color:#172230}pre{white-space:pre-wrap;font:inherit}@media print{body{margin:0}}</style></head><body><pre>'+esc(text)+'</pre><script src="/live-game.js?v=1"><\/script></body></html>');w.document.close();w.focus();w.print()}


