/* aviso: o Studio segue tocando em segundo plano; páginas com som próprio vão tocar junto */
let _stNotePage='',_stNoteT=0;
function studioPlaying(){try{const f=document.getElementById('iasd-studio-frame'),w=f&&f.contentWindow;return !!(w&&[...w.document.querySelectorAll('audio,video')].some(a=>!a.paused&&!a.ended&&a.readyState>2))}catch(e){return false}}
function studioPauseAll(){try{const w=document.getElementById('iasd-studio-frame').contentWindow;w.document.querySelectorAll('audio,video').forEach(a=>{try{a.pause()}catch(e){}})}catch(e){}hideStudioNote();stMiniUpdate()}
function hideStudioNote(){clearTimeout(_stNoteT);const n=document.getElementById('st-sound-note');if(n)n.classList.remove('on')}
function studioSoundNote(){
 const page=current;if(page===_stNotePage)return;_stNotePage=page;
 if(page==='Projeção'||!canUseSound()||!studioPlaying()){hideStudioNote();return}
 const withSound=['Jogo','Estudo','Mídia'].includes(page);
 let n=document.getElementById('st-sound-note');
 if(!n){const st=document.createElement('style');st.textContent='#st-sound-note{position:fixed;left:50%;bottom:calc(86px + env(safe-area-inset-bottom,0px));transform:translate(-50%,20px);z-index:9998;max-width:min(560px,calc(100vw - 24px));display:flex;gap:12px;align-items:center;padding:12px 14px;border-radius:14px;background:rgba(10,24,52,.96);color:#fff;border:1px solid rgba(140,172,255,.4);box-shadow:0 12px 34px rgba(0,0,0,.45);font:600 13px/1.4 Inter,system-ui,sans-serif;opacity:0;pointer-events:none;transition:.25s}#st-sound-note.on{opacity:1;transform:translate(-50%,0);pointer-events:auto}#st-sound-note.warn{border-color:#f5b73a}#st-sound-note span{flex:1}#st-sound-note button{border:0;border-radius:10px;padding:8px 12px;font:700 12px inherit;cursor:pointer;background:#2f6bff;color:#fff}#st-sound-note button.x{background:rgba(255,255,255,.12)}';document.head.appendChild(st);
  n=document.createElement('div');n.id='st-sound-note';n.setAttribute('role','status');document.body.appendChild(n)}
 n.className=withSound?'warn':'';
 n.innerHTML='<span>'+(withSound?'🔊 O áudio da Projeção continua tocando. Esta página também tem som, então os dois vão tocar juntos.':'🎵 O áudio da Projeção continua tocando em segundo plano.')+'</span><button type="button" onclick="studioPauseAll()">Pausar</button><button type="button" class="x" onclick="hideStudioNote()" aria-label="Fechar">✕</button>';
 requestAnimationFrame(()=>n.classList.add('on'));clearTimeout(_stNoteT);_stNoteT=setTimeout(hideStudioNote,withSound?14000:7000)
}
/* mini player flutuante: controla o áudio da Projeção de qualquer página */
function stAudioEl(){try{const f=document.getElementById('iasd-studio-frame');return f&&f.contentWindow.document.getElementById('sthAudio')}catch(e){return null}}
function stMiniToggle(){const a=stAudioEl();if(!a)return;const w=document.getElementById('iasd-studio-frame')?.contentWindow;if(w?.IASDAudio)w.IASDAudio.toggle(a);else if(a.paused)a.play().catch(()=>{});else a.pause();stMiniUpdate()}
function stMiniStop(){const a=stAudioEl();if(!a)return;try{const w=document.getElementById('iasd-studio-frame')?.contentWindow;if(w&&w.stFadePause){w.stFadePause(a,180,()=>{a.currentTime=0;stMiniUpdate()})}else{a.pause();a.currentTime=0}}catch(e){}stMiniUpdate()}
function stMiniUpdate(){
 let m=document.getElementById('st-mini');
 const a=canUseSound()&&current!=='Projeção'?stAudioEl():null;
 const active=!!(a&&a.src&&!a.ended&&(a.currentTime>0||!a.paused));
 if(!active){if(m)m.classList.remove('on');return}
 if(!m){const st=document.createElement('style');st.textContent='#st-mini{position:fixed;right:14px;bottom:calc(88px + env(safe-area-inset-bottom,0px));z-index:9997;display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:999px;background:rgba(10,24,52,.96);color:#fff;border:1px solid rgba(140,172,255,.4);box-shadow:0 10px 28px rgba(0,0,0,.45);font:700 12px Inter,system-ui,sans-serif;opacity:0;transform:translateY(12px);pointer-events:none;transition:.25s}#st-mini.on{opacity:1;transform:none;pointer-events:auto}#st-mini .t{max-width:130px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#st-mini .b{display:grid;place-items:center;width:32px;height:32px;border:0;border-radius:50%;background:#2f6bff;color:#fff;font-size:13px;cursor:pointer}#st-mini .b.s{background:rgba(255,255,255,.14)}#st-mini .b.g{background:transparent;width:auto;padding:0 4px;color:#9db4ff;font:700 11px inherit}#st-mini i{width:8px;height:8px;border-radius:50%;background:#3ddc84;animation:stmp 1.2s infinite}@keyframes stmp{50%{opacity:.25}}';document.head.appendChild(st);
  m=document.createElement('div');m.id='st-mini';m.innerHTML='<i></i><span class="t">Projeção</span><button class="b" type="button" data-k="p" onclick="stMiniToggle()"></button><button class="b s" type="button" aria-label="Parar" title="Parar" onclick="stMiniStop()">■</button><button class="b g" type="button" onclick="go(\'Projeção\')">Abrir</button>';document.body.appendChild(m)}
 const pb=m.querySelector('[data-k=p]');pb.textContent=a.paused?'▶':'❚❚';pb.setAttribute('aria-label',a.paused?'Tocar':'Pausar');
 m.querySelector('i').style.visibility=a.paused?'hidden':'visible';
 const mm=Math.floor(a.currentTime/60),ss=String(Math.floor(a.currentTime%60)).padStart(2,'0');
 m.querySelector('.t').textContent='Projeção · '+mm+':'+ss;
 m.classList.add('on')
}
/* pílula da música ambiente (YouTube): aparece fora da aba "Músicas ambientes" */
function stAmbWin(){try{const f=document.getElementById('iasd-studio-frame');return f&&f.contentWindow}catch(e){return null}}
function stAmbCtl(a){const w=stAmbWin();if(w&&w.ambCtl)w.ambCtl(a);stAmbUpdate()}
function stAmbOpen(){go('Projeção');setTimeout(()=>{try{const w=stAmbWin();w&&w.showTool&&w.showTool('ambient')}catch(e){}},300)}
function stAmbUpdate(){
 let m=document.getElementById('st-amb');
 const w=canUseSound()?stAmbWin():null;let ys=null,here=false;
 try{ys=w&&w.ambState?w.ambState():null;const pn=w&&w.document.getElementById('ambient');here=current==='Projeção'&&!!pn&&pn.offsetParent!==null&&getComputedStyle(pn).display!=='none'}catch(e){}
 const active=ys!==null&&ys!=='0'&&!here;   /* basta existir música ambiente carregada; o estado real (tocando/pausado) vem do YouTube quando disponível */
 if(!active){if(m)m.classList.remove('on');return}
 if(!m){const st=document.createElement('style');st.textContent='#st-amb{position:fixed;right:14px;bottom:calc(142px + env(safe-area-inset-bottom,0px));z-index:9997;display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:999px;background:rgba(10,24,52,.96);color:#fff;border:1px solid rgba(245,183,58,.55);box-shadow:0 10px 28px rgba(0,0,0,.45);font:700 12px Inter,system-ui,sans-serif;opacity:0;transform:translateY(12px);pointer-events:none;transition:.25s}#st-amb.on{opacity:1;transform:none;pointer-events:auto}#st-amb .b{display:grid;place-items:center;width:32px;height:32px;border:0;border-radius:50%;background:#2f6bff;color:#fff;font-size:13px;cursor:pointer}#st-amb .b.s{background:rgba(255,255,255,.14)}#st-amb .b.g{background:transparent;width:auto;padding:0 4px;color:#9db4ff;font:700 11px inherit}';document.head.appendChild(st);
  m=document.createElement('div');m.id='st-amb';m.innerHTML='<span>🎵 Música ambiente</span><button class="b" type="button" data-k="p" onclick="stAmbCtl(this.dataset.a)"></button><button class="b s" type="button" title="Fechar música" aria-label="Fechar música" onclick="stAmbCtl(\'close\')">✕</button><button class="b g" type="button" onclick="stAmbOpen()">Abrir</button>';document.body.appendChild(m)}
 const pb=m.querySelector('[data-k=p]');const playing=ys==='1'||ys==='3'||ys==='';pb.textContent=playing?'❚❚':'▶';pb.dataset.a=playing?'pause':'play';pb.setAttribute('aria-label',playing?'Pausar':'Tocar');
 m.classList.add('on')
}
