 sel.innerHTML='<option value="">Selecione o capítulo</option>'+Array.from({length:max},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'</option>').join('');
 $('bchapter').max=max;$('bchapter').value='';sel.value='';$('bverse').value='';$('bverseSelect').innerHTML='<option value="">Selecione o capítulo</option>';
