function syncBibleVerseSelect(value){if(/^\d+$/.test(value)&&Number(value)>0&&Array.from($('bverseSelect').options).some(o=>o.value===value))$('bverseSelect').value=value;else $('bverseSelect').value=''}
let iasdBible1911=null;
async function iasdGetBible1911(book,chapter){
 if(!iasdBible1911)iasdBible1911=fetch('https://cdn.jsdelivr.net/gh/BibliaJFAAL/JFAAL@main/original/1911-JFAAtualizada.json').then(r=>{if(!r.ok)throw Error('Fonte indisponível');return r.json()}).catch(e=>{iasdBible1911=null;throw e});
 const data=await iasdBible1911,books=Array.isArray(data)?data:(data.books||data.livros||data.data);
 const index=bibleBooks.findIndex(x=>x[1]===book);
 if(!Array.isArray(books)||books.length!==66||index<0)throw Error('Fonte incompleta');
 const item=books[index],chapters=item.chapters||item.capitulos||item.content;
 const chapterData=chapters?.[chapter-1],raw=Array.isArray(chapterData)?chapterData:(chapterData?.verses||chapterData?.versiculos);
 if(!Array.isArray(raw))throw Error('Capítulo indisponível');
 const verses=raw.map((v,i)=>({verse:Number(v?.number||v?.numero||i+1),text:typeof v==='string'?v:String(v?.text||v?.texto||'')})).filter(v=>v.text.trim());
 if(!verses.length||verses[0].verse!==1)throw Error('Capítulo incompleto');
 return verses
}
const iasdBibleJsonSources={
 acf:'https://cdn.jsdelivr.net/gh/thiagobodruk/biblia@master/json/acf.json',
 aa:'https://cdn.jsdelivr.net/gh/thiagobodruk/biblia@master/json/aa.json',
 nvi:'https://cdn.jsdelivr.net/gh/thiagobodruk/biblia@master/json/nvi.json'
};
const iasdBibleJsonCache=new Map();
async function iasdGetBibleJson(translation,book,chapter){
 const source=iasdBibleJsonSources[translation];if(!source)throw Error('Tradução local indisponível');
 let promise=iasdBibleJsonCache.get(translation);
 if(!promise){promise=fetch(source).then(r=>{if(!r.ok)throw Error('Fonte bíblica indisponível');return r.json()}).catch(e=>{iasdBibleJsonCache.delete(translation);throw e});iasdBibleJsonCache.set(translation,promise)}
 const data=await promise,index=bibleBooks.findIndex(x=>x[1]===book),item=Array.isArray(data)?data[index]:null;
 const raw=item?.chapters?.[Number(chapter)-1];if(!Array.isArray(raw))throw Error('Capítulo indisponível');
 const verses=raw.map((text,i)=>({verse:i+1,text:String(text||'')})).filter(v=>v.text.trim());
 if(!verses.length||verses[0].verse!==1)throw Error('Capítulo incompleto');
 return verses
}
async function fetchBibleChapter(book,chapter,requestedTranslation){
 const translation=requestedTranslation||$('btranslation')?.value||readerState.translation||'almeida';const key=book+'|'+chapter+'|'+translation;
 if(bibleChapterCache.has(key))return bibleChapterCache.get(key);
 const url='https://bible-api.com/'+encodeURIComponent(book+' '+chapter)+'?translation='+encodeURIComponent(translation)+'&single_chapter_book_matching=indifferent';
 const promise=(async()=>{
  if(iasdBibleJsonSources[translation]){try{return await iasdGetBibleJson(translation,book,Number(chapter))}catch(e){console.warn('JSON bíblico indisponível:',translation,e)}}
  if(translation==='almeida'){try{return await iasdGetBible1911(book,Number(chapter))}catch(e){console.warn('Almeida 1911 indisponível:',e)}}
  const response=await fetch(url);
  if(!response.ok)throw Error('Consulta indisponível ('+response.status+')');
  const result=await response.json();
  if(!Array.isArray(result.verses)||!result.verses.length)throw Error('Capítulo não encontrado');
  const verses=result.verses.filter(v=>Number(v.chapter)===Number(chapter)&&Number.isInteger(Number(v.verse))&&typeof v.text==='string').sort((a,b)=>a.verse-b.verse);
  if(!verses.length)throw Error('Capítulo não encontrado na tradução');
  // A consulta de versículos individuais permite recuperar eventuais lacunas da resposta do capítulo.
  const byNumber=new Map(verses.map(v=>[Number(v.verse),v]));
  const highest=Math.max(...byNumber.keys()),missing=Array.from({length:highest},(_,i)=>i+1).filter(n=>!byNumber.has(n));
  if(missing.length&&missing.length<=15){
   await Promise.all(missing.map(async n=>{
    try{const url='https://bible-api.com/'+encodeURIComponent(book+' '+chapter+':'+n)+'?translation='+encodeURIComponent(translation);
     const response=await fetch(url);if(!response.ok)return;
     const item=await response.json();const verse=item.verses?.find(v=>Number(v.chapter)===chapter&&Number(v.verse)===n&&typeof v.text==='string');
     if(verse)byNumber.set(n,verse);
    }catch(e){}
   }));
  }
  return [...byNumber.values()].sort((a,b)=>a.verse-b.verse);
 })();
 bibleChapterCache.set(key,promise);
 try{return await promise}catch(e){bibleChapterCache.delete(key);throw e}
}
async function updateBibleVerses(){
 const sel=$('bverseSelect');if(!sel)return;
 const book=$('bbook').value,chapter=Number($('bchapter').value),old=$('bverse').value,serial=++bibleRequestSerial;
 if(!chapter){sel.innerHTML='<option value="">Selecione o capítulo</option>';return}
 sel.innerHTML='<option value="">Carregando versículos…</option>';
 try{
  const verses=await fetchBibleChapter(book,chapter);
  if(serial!==bibleRequestSerial||!$('bbook')||book!==$('bbook').value||chapter!==Number($('bchapter').value))return;
  sel.innerHTML='<option value="">Selecione o versículo</option>'+verses.map(v=>'<option value="'+v.verse+'">'+v.verse+'</option>').join('');
  if(verses.some(v=>String(v.verse)===old))sel.value=old;
 }catch(e){
  if(serial!==bibleRequestSerial)return;
  sel.innerHTML='<option value="">Consulta indisponível — digite abaixo</option>';
  const out=$('bresult');if(out)out.textContent='Não foi possível carregar a lista agora. Você ainda pode digitar o versículo e tentar buscar.';
 }
}
async function readBibleChapter(){const book=$('bbook'),chapter=Number($('bchapter').value||$('bchapterSelect').value),out=$('bresult');if(!Number.isInteger(chapter)||chapter<1||chapter>(bibleChapterCounts[book.selectedIndex]||150)){out.textContent='Selecione um capítulo válido.';return}const ref=book.options[book.selectedIndex].text+' '+chapter;out.textContent='Carregando '+ref+'…';try{const verses=await fetchBibleChapter(book.value,chapter);const section=document.createElement('section');section.className='bible-result';const heading=document.createElement('h3');heading.textContent=ref;section.append(heading);for(const verse of verses){const p=document.createElement('p');p.style.cssText='line-height:1.85;margin:0 0 10px';const n=document.createElement('strong');n.textContent=verse.verse+' ';p.append(n,document.createTextNode(verse.text.trim()));section.append(p)}out.replaceChildren(section)}catch(e){out.textContent='Não foi possível carregar '+ref+': '+(e.message||'Verifique a conexão.')}}
async function searchBible(){
 const book=$('bbook'),chapter=Number($('bchapter').value||$('bchapterSelect').value),v=($('bverse').value||$('bverseSelect').value).trim(),out=$('bresult');
 if(!Number.isInteger(chapter)||chapter<1||chapter>(bibleChapterCounts[book.selectedIndex]||150)||!/^\d{1,3}(?:-\d{1,3})?$/.test(v)){out.textContent='Informe um capítulo e versículo válidos.';return}
 const [start,end]=v.split('-').map(Number);
 if(start<1||(end!==undefined&&(end<start||end-start>30))){out.textContent='Escolha um intervalo de até 31 versículos.';return}
 const ref=book.options[book.selectedIndex].text+' '+chapter+':'+v+' ('+($('btranslation')?.selectedOptions[0]?.text||'Almeida')+')';
 out.textContent='Buscando '+ref+'…';
 try{
  const verses=await fetchBibleChapter(book.value,chapter);
  const chosen=verses.filter(x=>x.verse>=start&&x.verse<=(end||start));
  if(chosen.length!==(end||start)-start+1||chosen.some((item,i)=>item.verse!==start+i))throw Error('Há versículos ausentes na resposta da fonte bíblica. Não serão exibidos textos incompletos. Tente novamente ou consulte outra edição licenciada.');
  const text=chosen.map(x=>x.text.trim()).join(' ').replace(/\s+/g,' ').trim();
  bibleResult={ref,text};
  out.innerHTML='<div class="bible-result"><span class="bible-result-eyebrow">PASSAGEM ENCONTRADA</span><h3>'+esc(ref)+'</h3><p>'+esc(text)+'</p><button class="primary" onclick="projectBible()" '+(canUseSound()?'':'disabled title="Exclusivo para sonoplastas"')+'>▶ Projetar na televisão</button></div>';
 }catch(e){bibleResult=null;out.innerHTML='<div class="bible-error">Não foi possível carregar '+esc(ref)+'. '+esc(e.message||'Verifique sua conexão e tente novamente.')+' <button onclick="searchBible()">Tentar novamente</button></div>'}
}
function projectBible(){
 if(!canUseSound()){go('Sonoplastia');return}
 if(!bibleResult)return;
 project('IASD_BIBLE:'+JSON.stringify(bibleResult));
 const el=$('bresult');if(el){const note=document.createElement('p');note.className='bible-projection-note';note.textContent='Passagem enviada ao projetor.';el.querySelectorAll('.bible-projection-note').forEach(n=>n.remove());el.append(note)}
}
function drawNames(){if(!canUseSound())return;const names=$('names').value.split('\n').map(x=>x.trim()).filter(Boolean);const pool=$('unique').checked?names.filter(n=>!data.sorteados.includes(n)):names;if(!pool.length){$('drawresult').textContent='Sem nomes disponíveis';return}const name=pool[Math.floor(Math.random()*pool.length)];data.sorteados.push(name);project(name);render();$('names').value=names.join('\n');$('drawresult').textContent='Sorteado: '+name}function drawNumber(){if(!canUseSound())return;const a=Number($('min').value),b=Number($('max').value);if(!Number.isInteger(a)||!Number.isInteger(b)||b<a){alert('Intervalo inválido');return}const n=a+Math.floor(Math.random()*(b-a+1));$('numresult').textContent='Número: '+n;project(String(n))}let mediaURL;function loadMedia(input){if(mediaURL)URL.revokeObjectURL(mediaURL);const file=input.files[0];if(!file)return;mediaURL=URL.createObjectURL(file);const el=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'img';$('player').innerHTML='<'+el+' src="'+mediaURL+'" controls style="max-width:100%;max-height:60vh" '+(el==='img'?'alt="Prévia"':'')+'></'+el+'>'}render();initCloud();loadCustomTabs();loadAssetFrames();